WITH lines AS (SELECT id, service, log_ts, level, latency_ms, status_code, key, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS key, value), flattened_attrs AS (SELECT latency_ms, status_code, value, CAST((status_code & 8) != 0 AS INT) AS has_fault, SHIFTRIGHT(status_code, 2) AS status_code_high FROM lines WHERE latency_ms <> 2250), filtered AS (SELECT *, COALESCE(latency_ms, 0) AS latency_ms_filled FROM flattened_attrs WHERE status_code BETWEEN 314 AND 382), base AS (SELECT latency_ms, status_code, has_fault, status_code_high, ROUND(has_fault * 0.9, 2) AS has_fault_adjusted FROM filtered WHERE status_code_high <> 2) SELECT status_code, status_code_high, has_fault_adjusted FROM base ORDER BY status_code_high DESC, has_fault_adjusted;
